using Servicio.RetazoMarket.Business.DTOs.Imagen;
namespace Servicio.RetazoMarket.Business.Validators;public static class ImagenValidator {public static IReadOnlyCollection<string> Validar(CrearImagenRequest r)=>r is null?["La solicitud no puede ser nula."]:Campos(r.id_producto,r.url,r.es_principal,r.orden);public static IReadOnlyCollection<string> Validar(ActualizarImagenRequest r){if(r is null)return ["La solicitud no puede ser nula."];var e=Campos(r.id_producto,r.url,r.es_principal,r.orden).ToList();if(r.id_imagen<=0)e.Insert(0,"El id de la imagen es inválido.");return e;}private static IReadOnlyCollection<string> Campos(int producto,string? url,string? principal,int orden){var e=new List<string>();if(producto<=0)e.Add("El producto es obligatorio.");if(string.IsNullOrWhiteSpace(url)||url.Trim().Length>500||!Uri.TryCreate(url.Trim(),UriKind.Absolute,out var uri)||uri.Scheme is not("http" or "https"))e.Add("La URL debe ser absoluta, HTTP/HTTPS y admitir hasta 500 caracteres.");if(principal?.Trim().ToUpperInvariant() is not("S" or "N"))e.Add("El indicador principal debe ser S o N.");if(orden<0)e.Add("El orden no puede ser negativo.");return e;}}
